INSERT INTO projects (id, developer_id, name, location, stage, delivery, confidence, summary, brochure_url, price_list_url, plans_url, media_url, video_url, drive_url, map_query, color, image_url, parking_price_usd, source_label, extra, updated_at) VALUES ('solana-2', 'unotres', 'Torre Solana 2', 'Las Lomas, Asunción', 'Pozo', '24 meses desde mayo de 2026', 'Confirmado', '34 unidades disponibles según la lista comercial vigente. Las dos filas 1D C sin código están bloqueada y reservada, por lo que no pueden ofrecerse.', 'https://drive.google.com/file/d/12yTs1bfFD-sDoepYN2jbGDLDC7TLIbaV/view', 'https://drive.google.com/file/d/173unhmAsCPzkQdc3WRpvTbNjgYg2c1rT/view', NULL, NULL, NULL, NULL, 'Torre Solana 2 Juan Max Boettner Asunción Paraguay', '#b99048', NULL, NULL, 'Lista vigente confirmada por el equipo', '{"inventoryAudit":{"reviewedAt":"2026-09-01","status":"Cotejado","checkedUnits":34,"areaCorrections":0,"addedUnits":0,"sources":[{"label":"Torre Solana2-Lista de precios.pdf","url":"https://drive.google.com/file/d/173unhmAsCPzkQdc3WRpvTbNjgYg2c1rT/view"}],"notes":["Precios y unidades cotejados contra el documento indicado. No equivale a confirmación comercial de disponibilidad hoy.","34 filas libres con identificador coinciden en precio y m² propios. Hay 2 filas libres 1D C sin código legible (pisos 1 y 4, 43,11 m²; USD 100.263 y 100.573); no se inventaron unidades.","La vigencia actual y las 34 unidades ofertables fueron confirmadas; las dos filas 1D C sin código no se ofrecen."],"pending":[],"sourceModifiedAt":"2026-08-21T03:12:34.000Z"},"resolvedFields":["inventoryAudit","delivery","validation","priceList","units","financing"]}', '2026-09-01');
