INSERT INTO projects (id, developer_id, name, location, stage, delivery, confidence, summary, brochure_url, price_list_url, plans_url, media_url, video_url, drive_url, map_query, color, image_url, parking_price_usd, source_label, extra, updated_at) VALUES ('avanza-harbor', 'grupo-avanza', 'HARBOR', 'Avenida del Yacht, Lambaré', 'Pozo', 'Requiere confirmación', 'Requiere confirmación', 'Condominio cerrado de 20 casas desde 127 m² construidos, lote promedio de 127 m² y dos cocheras. El plano comercial no permite confirmar qué casas siguen libres; no se cargan unidades sin una lista vigente.', 'https://drive.google.com/file/d/1H0dzQMh1bAVloS1Klto1OMLoY9DU2DMt/view', NULL, 'https://drive.google.com/drive/folders/1fSTLjcLON99qmsfRIj8rS3jXRwPU08Z0', 'https://drive.google.com/drive/folders/1YF0syIm9FAZsDTri_tfbDA4TlMeTP0aY', 'https://drive.google.com/drive/folders/1tKyP-Bv0Z5i0OKrQzn4Sbsd7-wkR2RHr', 'https://drive.google.com/drive/folders/1t3J3MQFFPiLKBdMFl91P3JaB_PdaooHh', 'HARBOR Avenida del Yacht Lambare Paraguay', '#47788b', 'https://lh3.googleusercontent.com/d/1CJyUyAeyaaqAyM8a5KgqZihHvnMUm5Zd=w1600', NULL, NULL, '{"inventoryAudit":{"reviewedAt":"2026-08-27","status":"Sin cotejo","checkedUnits":0,"areaCorrections":0,"addedUnits":0,"sources":[],"notes":["Carpetas comerciales revisadas: material visual/documental, sin lista vigente de unidades, precios y superficies."],"pending":[]},"consultationPolicy":"Material de referencia. Confirmar disponibilidad, precio, entrega y financiación ante cada interesado.","resolvedFields":["inventoryAudit","delivery","validation","priceList","units","financing"]}', '2026-08-05');
INSERT INTO projects (id, developer_id, name, location, stage, delivery, confidence, summary, brochure_url, price_list_url, plans_url, media_url, video_url, drive_url, map_query, color, image_url, parking_price_usd, source_label, extra, updated_at) VALUES ('r-bulnes', 'grupo-delgado-fds', 'R Bulnes', 'Gonzalo Bulnes esquina Del Maestro, Asunción', 'Terminado', 'Entregado en febrero de 2026 — listo para ocupación', 'Confirmado', '10 unidades disponibles. Cochera opcional USD 20.000 y baulera opcional USD 3.000. Financiación directa hasta 36 meses; entrega y cronograma se negocian con cada comprador.', '/brochures/r-bulnes.pdf', NULL, NULL, NULL, NULL, NULL, 'Gonzalo Bulnes esquina Del Maestro Asunción Paraguay', '#0b3b34', NULL, 20000, 'Lista: agosto de 2026', '{"inventoryAudit":{"reviewedAt":"2026-09-01","status":"Cotejado","checkedUnits":10,"areaCorrections":0,"addedUnits":10,"sources":[],"notes":["Lista de agosto de 2026 y brochure oficial revisados."],"pending":[]},"brochureDetails":{"reviewedAt":"2026-09-01","building":"38 departamentos: 12 studios, 15 de 1 dormitorio, 7 de 2 dormitorios y 4 de 3 dormitorios. El edificio ya fue entregado.","amenities":["Recepción","Estar común por piso","Gimnasio","Quincho","Terraza","Piscina","Deck","Laundry"],"finishes":["Balcones en las tipologías residenciales","Kitchenette en studios","Parrilla en las tipologías de 2 dormitorios"],"typologies":[{"label":"Studio","areaM2":28.51,"bathrooms":1,"page":22},{"label":"1 dormitorio sobre Bulnes","areaM2":55.47,"bathrooms":2,"page":21},{"label":"1 dormitorio sobre Del Maestro","areaM2":48.14,"bathrooms":2,"page":25},{"label":"2 dormitorios","areaM2":82.2,"bathrooms":3,"page":23},{"label":"2 dormitorios en esquina","areaM2":92.62,"bathrooms":3,"page":24}],"sourceNotes":["Áreas tomadas de la lista comercial de agosto de 2026; el brochure no discrimina superficies por tipología.","El brochure también identifica unidades de 3 dormitorios, pero no publica su superficie en la ficha revisada."]},"consultationPolicy":"Disponibilidad según lista de agosto de 2026. Reconfirmar condiciones negociadas antes de emitir propuesta.","resolvedFields":["inventoryAudit","delivery","validation","priceList","units","financing"]}', '2026-08-26');
INSERT INTO projects (id, developer_id, name, location, stage, delivery, confidence, summary, brochure_url, price_list_url, plans_url, media_url, video_url, drive_url, map_query, color, image_url, parking_price_usd, source_label, extra, updated_at) VALUES ('r-las-lomas', 'grupo-delgado-fds', 'R5 Las Lomas', 'Pastor Filártiga esquina Dr. Carlos Abdala, Las Lomas, Asunción', 'Pozo', 'A consultar al cotizar', 'Confirmado', '8 departamentos de 1 dormitorio disponibles. Cinco cocheras con baulera opcionales por USD 23.000. Plan estándar: 30% inicial, 60% en 15 cuotas iguales y 10% en la posesión.', '/brochures/r-las-lomas.pdf', 'https://drive.google.com/file/d/16NTblM2sLm_HpMV5zJjUXiW5BYXXcAPo/view?usp=drivesdk', NULL, NULL, NULL, NULL, 'Pastor Filártiga esquina Dr. Carlos Abdala Las Lomas Asunción Paraguay', '#123c35', '/projects/r5-las-lomas/fachada.jpg', 23000, 'Lista: agosto de 2026', '{"inventoryAudit":{"reviewedAt":"2026-09-01","status":"Cotejado","checkedUnits":8,"areaCorrections":0,"addedUnits":8,"sources":[],"notes":["Brochure de julio y lista de agosto de 2026 revisados."],"pending":[]},"brochureDetails":{"reviewedAt":"2026-09-01","building":"Proyecto residencial en Las Lomas con distribuciones flexibles, balcones y zona de esparcimiento en la azotea.","amenities":["Zona de esparcimiento en la azotea"],"finishes":["Balcones","Iluminación natural","Distribuciones funcionales"],"typologies":[{"label":"1 dormitorio A","areaM2":52.75,"bathrooms":2,"page":4},{"label":"1 dormitorio C","areaM2":31.15,"bathrooms":1,"page":6},{"label":"1 dormitorio E","areaM2":22.8,"bathrooms":1,"page":8},{"label":"1 dormitorio F","areaM2":37.16,"bathrooms":1,"page":10},{"label":"1 dormitorio B","areaM2":62.5,"bathrooms":2,"page":12},{"label":"1 dormitorio D","areaM2":33.7,"bathrooms":1,"page":14}],"sourceNotes":["El brochure documenta seis tipologías; la disponibilidad y los precios provienen de la lista separada de agosto de 2026.","Las cocheras disponibles incluyen 12,5 m² de estacionamiento y 0,9 m² de baulera."]},"consultationPolicy":"La fecha de entrega y la disponibilidad final se consultan al preparar cada propuesta.","resolvedFields":["inventoryAudit","delivery","validation","priceList","units","financing"],"parkingIncludesStorage":true}', '2026-08-04');
INSERT INTO projects (id, developer_id, name, location, stage, delivery, confidence, summary, brochure_url, price_list_url, plans_url, media_url, video_url, drive_url, map_query, color, image_url, parking_price_usd, source_label, extra, updated_at) VALUES ('r-andrade', 'grupo-delgado-fds', 'R Andrade', 'Dr. Morra y O''Higgins, Villa Morra, Asunción', 'Pozo', '4.º trimestre de 2027', 'Confirmado', '27 studios amoblados y equipados disponibles, desde USD 66.950. Plan estándar 30% + 15 cuotas por el 60% + 10% en posesión. Pool de renta previsto para el 1.er trimestre de 2028.', '/brochures/r-andrade.pdf', '/brochures/r-andrade.pdf#page=15', NULL, NULL, NULL, NULL, 'Dr. Morra y O''Higgins Villa Morra Asunción Paraguay', '#153d35', '/projects/r-andrade/fachada.jpg', NULL, 'Lista incluida en el brochure: agosto de 2026', '{"inventoryAudit":{"reviewedAt":"2026-09-01","status":"Cotejado","checkedUnits":27,"areaCorrections":0,"addedUnits":27,"sources":[],"notes":["Brochure con lista de agosto, plan de pago y proyección de rentabilidad revisado."],"pending":[]},"brochureDetails":{"reviewedAt":"2026-09-01","building":"Edificio de studios en Villa Morra. Las unidades ofertadas entre los pisos 2 y 7 se publican totalmente equipadas y amobladas.","amenities":["Azotea con espacio de esparcimiento","Pool de renta para inversores","Showroom virtual"],"finishes":["Unidad equipada","Unidad amoblada","Balcón","Distribución integrada"],"typologies":[{"label":"Studio","areaM2":30.17,"bathrooms":1,"page":4}],"sourceNotes":["La lista de agosto de 2026 publica superficies entre 28,35 y 30,17 m²; 30,17 m² es la tipología ilustrada en el brochure.","Proyección del pool: ocupación 80%-90%, tarifa diaria USD 50-65, margen neto 55%-60%, fee de administración 15%-20% y ROI 12%-15%.","El reglamento prevé vocación de renta corta por 15 años, renovable cada 5 años. Puesta en marcha estimada: 1.er trimestre de 2028."]},"consultationPolicy":"Rentabilidad, ocupación y tarifa son proyecciones del brochure, no resultados garantizados. Reconfirmar stock antes de cotizar.","resolvedFields":["inventoryAudit","delivery","validation","priceList","units","financing"]}', '2026-08-19');
